"""Read-only post-completion replay; preserve the exact saved GP covariance.

No training, checkpoint selection, or modification of frozen study artifacts.
"""
import json
from pathlib import Path
import numpy as np
import torch
from common import arrays, concordance, cuda, sha
from training import make_model
from adapter import cached_scores

run = Path('/output')
frozen = json.loads((run/'SCORER_FREEZE.json').read_text())
selected = json.loads((run/'SELECTION.json').read_text())
published = json.loads((run/'results/RESULTS.json').read_text())
members = {r['name']: r for r in frozen['members']}
device = cuda()
panels = {}
for cell in ('C1', 'C2', 'C3'):
    for cohort in ('legacy', 'added'):
        panels[f'test_{cohort}_{cell}'] = arrays(f'/truth/{cohort}/{cell}.npz')
panels['development_legacy_C3'] = arrays('/data/legacy/development_00.npz')
panels['development_added_C3'] = arrays('/data/development/added/C3.npz')
models = {
    'selected': f"scaled_{selected['selected']['budget']}",
    'fresh_control': f"scaled_{selected['fresh_control']['budget']}",
    'ipin_tuna_frozen': 'baseline',
}
predictions = {panel: {} for panel in panels}
for label, prefix in models.items():
    sums = {name: np.zeros(len(data['a']), np.float64) for name, data in panels.items()}
    for seed in (20260803, 20260817, 20260831):
        member = members[f'{prefix}_seed{seed}']
        for key in ('weights', 'features'):
            assert sha(run/member[key]['path']) == member[key]['sha256']
        model = make_model(seed, device)
        state = torch.load(run/member['weights']['path'], map_location=device, weights_only=True)
        model.load_state_dict(state, strict=True)
        # Mark fitted BEFORE eval, preventing native float32 pinv from replacing
        # the checkpoint's training-only covariance.
        model.gp_layer.fitted = True
        model.eval()
        assert torch.equal(model.gp_layer.covariance, state['gp_layer.covariance'])
        z = torch.as_tensor(np.load(run/member['features']['path'], allow_pickle=False), device=device)
        for name, data in panels.items():
            sums[name] += cached_scores(model, z, data['a'], data['b']).astype(np.float64) / 3
        assert torch.equal(model.gp_layer.covariance, state['gp_layer.covariance'])
        print(json.dumps({'replayed': label, 'seed': seed}), flush=True)
        del model, state, z
    for name in panels:
        predictions[name][label] = sums[name]

comparison = {}
for cell in ('C1', 'C2', 'C3'):
    data = {
        'test_1': panels[f'test_legacy_{cell}'],
        'test_1_reconciled': arrays(f'/truth/reconciled/{cell}.npz'),
        'test_added': panels[f'test_added_{cell}'],
    }
    for view, panel in data.items():
        pred = predictions[f"test_{'added' if view == 'test_added' else 'legacy'}_{cell}"]
        key = cell + ':' + view
        comparison[key] = {}
        for label in models:
            point = concordance(pred[label], panel['positive'], panel['weight'])
            old = published['test'][key]['models'][label]['PU_concordance']
            comparison[key][label] = {'saved_covariance_replay': point, 'published': old, 'difference': point-old}
    key = cell + ':test_2_macro'
    comparison[key] = {}
    for label in models:
        point = (comparison[cell+':test_1_reconciled'][label]['saved_covariance_replay'] + comparison[cell+':test_added'][label]['saved_covariance_replay'])/2
        old = published['test'][key]['models'][label]['PU_concordance']
        comparison[key][label] = {'saved_covariance_replay': point, 'published': old, 'difference': point-old}

development = {}
for label in models:
    vals = {}
    for view, data, cohort in (
        ('dev_1', panels['development_legacy_C3'], 'legacy'),
        ('dev_1_reconciled', arrays('/data/development/reconciled/C3.npz'), 'legacy'),
        ('dev_added', panels['development_added_C3'], 'added'),
    ):
        vals[view] = concordance(predictions[f'development_{cohort}_C3'][label], data['positive'], data['weight'])
    vals['dev_2_macro'] = .5*(vals['dev_1_reconciled']+vals['dev_added'])
    reference = selected['selected']['metrics'] if label=='selected' else selected['fresh_control']['metrics'] if label=='fresh_control' else None
    development[label] = {'saved_covariance_replay': vals, 'selection': reference}

result = {
    'purpose': 'Post-completion numerical replay audit, not model reselection',
    'selection_sha256': sha(run/'SELECTION.json'),
    'scorer_freeze_sha256': sha(run/'SCORER_FREEZE.json'),
    'original_artifacts_modified': False,
    'training_performed': False,
    'exact_saved_covariance_retained': True,
    'test_point_comparison': comparison,
    'C3_development': development,
    'maximum_absolute_test_point_change': max(abs(v['difference']) for row in comparison.values() for v in row.values()),
}
Path('/review/SCORER_REPLAY_REVIEW.json').write_text(json.dumps(result, indent=2, sort_keys=True)+'\n')
print(json.dumps(result), flush=True)
